1	const ITEM_BASE_PREMIUM: Record<string, number> = {
2	  sword: 100,
3	  amulet: 60,
4	  staff: 80,
5	  potion: 40,
6	  rune: 25,
7	  moonstone: 25,
8	};
9	
10	const KNOWN_ITEM_TYPES = Object.keys(ITEM_BASE_PREMIUM);
11	
12	function countByType<T>(entries: T[], typeOf: (entry: T) => string): Map<string, number> {
13	  const counts = new Map<string, number>();
14	  for (const entry of entries) {
15	    const type = typeOf(entry);
16	    counts.set(type, (counts.get(type) ?? 0) + 1);
17	  }
18	  return counts;
19	}
20	
21	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
22	const COMPONENT_BLOCK_SIZE = 3;
23	const COMPONENT_BLOCK_PREMIUM = 60;
24	
25	function formsComponentBlock(type: string, count: number): boolean {
26	  return COMPONENT_TYPES.has(type) && count === COMPONENT_BLOCK_SIZE;
27	}
28	
29	function premiumForTypeGroup(type: string, count: number): number {
30	  return formsComponentBlock(type, count)
31	    ? COMPONENT_BLOCK_PREMIUM
32	    : ITEM_BASE_PREMIUM[type] * count;
33	}
34	
35	export function basePremium(items: { type: string }[]): number {
36	  let total = 0;
37	  for (const [type, count] of countByType(items, (item) => item.type)) {
38	    total += premiumForTypeGroup(type, count);
39	  }
40	  return total;
41	}
42	
43	const CURSE_SURCHARGE = 0.5;
44	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
45	const HIGH_ENCHANTMENT_THRESHOLD = 5;
46	
47	function isHighEnchantment(enchantment: number | undefined): boolean {
48	  return enchantment !== undefined && enchantment >= HIGH_ENCHANTMENT_THRESHOLD;
49	}
50	
51	type InsuredItem = { type: string; material?: string; cursed?: boolean; enchantment?: number };
52	
53	function itemSurchargeRate(item: InsuredItem): number {
54	  const curseRate = item.cursed ? CURSE_SURCHARGE : 0;
55	  const enchantmentRate = isHighEnchantment(item.enchantment) ? HIGH_ENCHANTMENT_SURCHARGE : 0;
56	  return curseRate + enchantmentRate;
57	}
58	
59	function itemBasePremium(item: InsuredItem): number {
60	  return ITEM_BASE_PREMIUM[item.type];
61	}
62	
63	function itemPolicyPremium(item: InsuredItem): number {
64	  return itemBasePremium(item) * (1 + itemSurchargeRate(item));
65	}
66	
67	export function policyBasePremium(items: InsuredItem[]): number {
68	  return items.reduce((total, item) => total + itemPolicyPremium(item), 0);
69	}
70	
71	const LOYALTY_DISCOUNT = 0.2;
72	const LOYALTY_YEARS_THRESHOLD = 2;
73	const FIRST_INSURANCE_SURCHARGE = 0.1;
74	const PROCESSING_FEE = 5;
75	
76	type Customer = { yearsWithMHPCO: number };
77	
78	function assertKnownItemTypes(items: InsuredItem[]): void {
79	  const unknownItem = items.find((item) => !KNOWN_ITEM_TYPES.includes(item.type));
80	  if (unknownItem) {
81	    throw new Error(`Unknown item type: ${unknownItem.type}`);
82	  }
83	}
84	
85	function isLoyalCustomer(customer: Customer): boolean {
86	  return customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
87	}
88	
89	const FOLLOWUP_DISCOUNT = 0.15;
90	
91	function policyWideRate(customer: Customer, isFollowUpContract: boolean): number {
92	  const loyaltyRate = isLoyalCustomer(customer) ? LOYALTY_DISCOUNT : 0;
93	  const followupRate = isFollowUpContract ? FOLLOWUP_DISCOUNT : 0;
94	  return FIRST_INSURANCE_SURCHARGE - loyaltyRate - followupRate;
95	}
96	
97	function itemQuotePremium(
98	  item: InsuredItem,
99	  customer: Customer,
100	  isFollowUpContract: boolean
101	): number {
102	  return (
103	    itemBasePremium(item) *
104	    (1 + itemSurchargeRate(item) + policyWideRate(customer, isFollowUpContract))
105	  );
106	}
107	
108	export function quote(
109	  customer: Customer,
110	  items: InsuredItem[],
111	  isFollowUpContract: boolean = false
112	): number {
113	  assertKnownItemTypes(items);
114	
115	  const premium =
116	    items.reduce((total, item) => total + itemQuotePremium(item, customer, isFollowUpContract), 0) +
117	    PROCESSING_FEE;
118	  return Math.ceil(premium);
119	}
120	
121	const ITEM_INSURANCE_VALUE: Record<string, number> = {
122	  sword: 1000,
123	  amulet: 600,
124	  staff: 800,
125	  potion: 400,
126	  rune: 250,
127	  moonstone: 250,
128	};
129	
130	const DEDUCTIBLE = 100;
131	const CAP_MULTIPLIER = 2;
132	
133	type PolicyItem = {
134	  type: string;
135	  material?: string;
136	  enchantment?: number;
137	  cursed?: boolean;
138	};
139	type Damage = { itemType: string; amount: number };
140	
141	function insuranceSum(policyItems: PolicyItem[]): number {
142	  return policyItems.reduce((sum, item) => sum + ITEM_INSURANCE_VALUE[item.type], 0);
143	}
144	
145	const HIGH_ENCHANTMENT_DAMAGE_THRESHOLD = 8;
146	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
147	const STANDARD_REIMBURSEMENT_RATE = 1;
148	
149	// Dragon-material items are reimbursed at the standard rate today; no test
150	// yet distinguishes them from other materials. Revisit when a dragon-only
151	// clause (e.g. full reimbursement bypassing another reduction) is specified.
152	function reimbursementRate(item: PolicyItem): number {
153	  if (item.enchantment !== undefined && item.enchantment >= HIGH_ENCHANTMENT_DAMAGE_THRESHOLD) {
154	    return HIGH_ENCHANTMENT_REIMBURSEMENT_RATE;
155	  }
156	  return STANDARD_REIMBURSEMENT_RATE;
157	}
158	
159	function damagePayout(damage: Damage, policyItems: PolicyItem[]): number {
160	  const item = policyItems.find((policyItem) => policyItem.type === damage.itemType);
161	  const rate = item ? reimbursementRate(item) : STANDARD_REIMBURSEMENT_RATE;
162	  return damage.amount * rate - DEDUCTIBLE;
163	}
164	
165	function assertNonNegativeDamages(damages: Damage[]): void {
166	  const negativeDamage = damages.find((damage) => damage.amount < 0);
167	  if (negativeDamage) {
168	    throw new Error(`Damage amount cannot be negative: ${negativeDamage.amount}`);
169	  }
170	}
171	
172	function assertDamagesWithinPolicy(policyItems: PolicyItem[], damages: Damage[]): void {
173	  const insuredCounts = countByType(policyItems, (item) => item.type);
174	  const damageCounts = countByType(damages, (damage) => damage.itemType);
175	  for (const [itemType, damageCount] of damageCounts) {
176	    if (damageCount > (insuredCounts.get(itemType) ?? 0)) {
177	      throw new Error(`More damaged items of type ${itemType} than insured`);
178	    }
179	  }
180	}
181	
182	export function claim(
183	  policyItems: PolicyItem[],
184	  damages: Damage[],
185	  priorPayout: number = 0
186	): { payout: number; remainingCap: number } {
187	  assertNonNegativeDamages(damages);
188	  assertDamagesWithinPolicy(policyItems, damages);
189	
190	  const desiredPayout = Math.floor(
191	    damages.reduce((sum, damage) => sum + damagePayout(damage, policyItems), 0)
192	  );
193	  const availableCap = CAP_MULTIPLIER * insuranceSum(policyItems) - priorPayout;
194	  const payout = Math.min(desiredPayout, availableCap);
195	  const remainingCap = availableCap - payout;
196	  return { payout, remainingCap };
197	}
