1	import { readFileSync } from "node:fs";
2	import { quote, claim } from "./claim-office.js";
3	
4	type QuoteStep = { op: "quote"; items: { type: string }[] };
5	type ClaimStep = {
6	  op: "claim";
7	  policy: number;
8	  incident: { cause: string; damages: { itemType: string; amount: number }[] };
9	};
10	type Step = QuoteStep | ClaimStep;
11	
12	type Scenario = {
13	  customer: { yearsWithMHPCO: number };
14	  steps: Step[];
15	};
16	
17	const input = readFileSync(0, "utf-8");
18	const scenario: Scenario = JSON.parse(input);
19	
20	const policyItemsByStep = new Map<number, { type: string }[]>();
21	const payoutByStep = new Map<number, number>();
22	let quoteCount = 0;
23	
24	function handleQuoteStep(step: QuoteStep, stepIndex: number): unknown {
25	  const isFollowUpContract = quoteCount > 0;
26	  quoteCount += 1;
27	  const premium = quote(scenario.customer, step.items, isFollowUpContract);
28	  policyItemsByStep.set(stepIndex, step.items);
29	  return { premium };
30	}
31	
32	function handleClaimStep(step: ClaimStep): unknown {
33	  const policyItems = policyItemsByStep.get(step.policy)!;
34	  const priorPayout = payoutByStep.get(step.policy) ?? 0;
35	  const { payout, remainingCap } = claim(policyItems, step.incident.damages, priorPayout);
36	  payoutByStep.set(step.policy, priorPayout + payout);
37	  return { payout, remainingCap };
38	}
39	
40	const results = scenario.steps.map((step, stepIndex) =>
41	  step.op === "quote" ? handleQuoteStep(step, stepIndex) : handleClaimStep(step)
42	);
43	
44	process.stdout.write(JSON.stringify({ results }));
